.app {
  display: grid;
  grid-template-columns: 250px 1fr;
  min-height: 100vh;
}

.app--sidebar-collapsed {
  grid-template-columns: auto 1fr;
}

.app__sidebar-wrapper {
  position: sticky;
  top: 0;
  height: 100vh;
  overflow: visible;
}

