  align-items: center;
  justify-content: space-between;
  padding: 12px 24px;
  border-bottom: 1px solid var(--color-border-light);
  background: var(--color-bg-primary);
}

.app__mode-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--color-text-secondary);
}

.app-loading,
