.memories-panel {
  padding: 0;
}

.memories-panel__empty {
  font-size: 13px;
  color: var(--color-text-faint);
  padding: 0;
  margin: 0;
}

.memories-panel__section {
  margin-bottom: 12px;
}

.memories-panel__section-title {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--color-text-muted);
  margin: 0 0 6px;
  padding: 0;
}

.memories-panel__list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.memories-panel__item {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 6px 8px;
  border-radius: 6px;
  border: 1px solid var(--color-border-light);
  margin-bottom: 4px;
  cursor: pointer;
}

.memories-panel__item:hover {
  border-color: var(--color-border-medium);
}

.memories-panel__text {
  flex: 1;
  font-size: 13px;
  color: var(--color-text-primary);
  line-height: 1.4;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.memories-panel__delete-btn {
  background: none;
  border: none;
  cursor: pointer;
  color: var(--color-text-muted);
  padding: 0 2px;
  flex-shrink: 0;
  opacity: 1;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}

.memories-panel__delete-btn:hover {
  color: var(--color-error);
}

/* Detail modal */

.memory-detail-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

.memory-detail-modal {
  background: var(--color-bg-primary);
  border: 1px solid var(--color-border-medium);
  border-radius: 12px;
  padding: 24px;
  width: 560px;
  max-width: 90vw;
  max-height: 80vh;
  display: flex;
  flex-direction: column;
}

.memory-detail-modal__header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
}

.memory-detail-modal__category {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--color-accent-primary);
}

.memory-detail-modal__close {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 20px;
  color: var(--color-text-muted);
  padding: 0 4px;
  line-height: 1;
  margin-left: auto;
}

.memory-detail-modal__close:hover {
  color: var(--color-text-primary);
}

